test.describe('Streak Counter', () => {
  test.beforeEach(async ({ page }) => {
    // Setup: Navigate to the dashboard and authenticate
    await page.goto('/dashboard')
    // Mock authentication
    await page.evaluate(() => {
      window.localStorage.setItem('auth-token', 'test-token')
    })
    // Create test user with streak
    await page.evaluate(() => {
      window.localStorage.setItem('user-data', JSON.stringify({
        streak: 5,
        pairedCoupleId: 'test-couple'
      }))
    })
  })

  test('should display current streak', async ({ page }) => {
    // Arrange: Ensure user has a streak
    // Wait for streak counter to load
    await page.waitForSelector('[data-testid="streak-counter"]')

    // Act: Navigate to the streak counter
    // No need to click since it's visible by default

    // Assert: Verify streak is displayed
    const streakElement = page.locator('[data-testid="streak-value"]')
    await expect(streakElement).toBeVisible()
    await expect(streakElement).toHaveText('5')
  })

  test('should increment streak on daily login', async ({ page }) => {
    // Arrange: Get current streak value
    const initialStreak = await page.locator('[data-testid="streak-value"]').innerText()

    // Act: Simulate daily login
    // Mock API response for login
    await page.route('**/api/login', route => {
      route.fulfill({
        status: 200,
        body: JSON.stringify({ success: true })
      })
    })
    // Trigger login
    await page.evaluate(() => {
      window.dispatchEvent(new Event('storage'))
    })

    // Wait for streak update
    await page.waitForFunction(() => {
      const streakElement = document.querySelector('[data-testid="streak-value"]')
      return streakElement?.textContent === '6'
    })

    // Assert: Verify streak incremented
    const newStreak = await page.locator('[data-testid="streak-value"]').innerText()
    expect(parseInt(newStreak)).toBe(parseInt(initialStreak) + 1)
  })

  test('should show streak animation on load', async ({ page }) => {
    // Arrange: Wait for animation to complete
    await page.waitForSelector('[data-testid="streak-counter"]')

    // Assert: Verify animation played
    const streakCounter = page.locator('[data-testid="streak-counter"]')
    const opacity = await streakCounter.evaluate(el => window.getComputedStyle(el).opacity)
    expect(parseFloat(opacity)).toBeGreaterThan(0.9)
  })

  test.afterEach(async ({ page }, testInfo) => {
    // Capture screenshot on failure
    if (testInfo.status !== 'passed') {
      await page.screenshot({ path: `test-results/${testInfo.title}.png` })
      // Capture video
      await page.video()?.saveAs(`test-results/${testInfo.title}.webm`)
      // Capture trace
      await page.context().tracing.stop({
        path: `test-results/${testInfo.title}.trace.zip`
      })
    }
  })
})
